CREATE TABLE public.wa_accounts (user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE, phone_number_id text NOT NULL UNIQUE, waba_id text NOT NULL, display_phone_number text NOT NULL DEFAULT '', token_ciphertext text NOT NULL, active boolean NOT NULL DEFAULT true, connected_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.wa_accounts TO service_role;
ALTER TABLE public.wa_accounts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.wa_contacts (user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, wa_id text NOT NULL, contact_name text NOT NULL DEFAULT '', last_preview text NOT NULL DEFAULT '', last_message_at timestamptz NOT NULL DEFAULT now(), watched boolean NOT NULL DEFAULT false, monitored_since timestamptz, PRIMARY KEY(user_id,wa_id));
GRANT SELECT,UPDATE ON public.wa_contacts TO authenticated;
GRANT ALL ON public.wa_contacts TO service_role;
ALTER TABLE public.wa_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.wa_contacts FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY contacts_update ON public.wa_contacts FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE FUNCTION public.wa_monitor_time() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.watched AND NOT OLD.watched THEN NEW.monitored_since=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER wa_monitor_time BEFORE UPDATE ON public.wa_contacts FOR EACH ROW EXECUTE FUNCTION public.wa_monitor_time();
CREATE TABLE public.wa_messages (user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, id text NOT NULL, wa_id text NOT NULL, direction text NOT NULL CHECK(direction IN ('in','out')), body text NOT NULL DEFAULT '', sent_at timestamptz NOT NULL, ai_status text NOT NULL DEFAULT 'pending' CHECK(ai_status IN ('pending','ignored','created','not_appointment','error','analyzing')), ai_error text, appointment_id text, appointment_title text, appointment_date text, appointment_time text, PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,wa_id) REFERENCES public.wa_contacts(user_id,wa_id) ON DELETE CASCADE);
GRANT SELECT ON public.wa_messages TO authenticated;
GRANT ALL ON public.wa_messages TO service_role;
ALTER TABLE public.wa_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.wa_messages FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE INDEX wa_messages_pending ON public.wa_messages(user_id,ai_status,sent_at);
CREATE TABLE public.whatsapp_webhook_events (id bigserial PRIMARY KEY,delivery_id text NOT NULL UNIQUE,event text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,processing_error text,attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.whatsapp_webhook_events TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.whatsapp_webhook_events_id_seq TO service_role;
ALTER TABLE public.whatsapp_webhook_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX whatsapp_events_pending ON public.whatsapp_webhook_events(attempts,received_at) WHERE processed_at IS NULL;
CREATE TABLE public.wa_oauth_states (state text PRIMARY KEY,user_id uuid NOT NULL,expires_at timestamptz NOT NULL);
GRANT ALL ON public.wa_oauth_states TO service_role;
ALTER TABLE public.wa_oauth_states ENABLE ROW LEVEL SECURITY;